import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Primary CTA node – a textured plane positioned at the bottom of the hub-home scene.
 * Loads the orb-decor.png texture, applies a subtle tint from the accent color, and
 * provides cleanup for all disposable resources.
 *
 * @param {Object} config - PrismNode configuration
 * @param {Object} ctx - Runtime context with loaders, primitives, etc.
 * @returns {THREE.Group}
 */
export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ── Scene placement ──────────────────────────────────────────────
  const position = config.scenePosition || { x: 0, y: -2.85, z: 0.2 };
  const rotation = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scale   = config.sceneScale   || { x: 1, y: 1, z: 1 };

  // ── Size – derived from atlas aspect ratio (512×320 ≈ 1.6:1) ────
  const width  = 2.0;
  const height = width * (320 / 512); // ≈ 1.25

  // ── Construct group ──────────────────────────────────────────────
  const group = new THREE.Group();
  group.position.set(position.x, position.y, position.z);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.set(scale.x, scale.y, scale.z);

  // ── Geometry & Material ──────────────────────────────────────────
  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: '#ffffff',
    transparent: false,
    side: THREE.DoubleSide,
  });

  // Temporary white texture – will be replaced when image loads
  const tempTexture = ctx.THREE.Texture?._emptyTexture
    ? ctx.THREE.Texture._emptyTexture()
    : new ctx.THREE.DataTexture(new Uint8Array([255,255,255,255]), 1, 1, ctx.THREE.RGBAFormat);
  tempTexture.needsUpdate = true;
  material.map = tempTexture;
  material.needsUpdate = true;

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // ── Load texture ──────────────────────────────────────────────────
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  let loadedTexture = null;

  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    loadedTexture = tex;
    material.map = tex;
    material.needsUpdate = true;

    // Subtle accent tint over the image (engineered surface feel)
    // Using a uniform tint blend – the image remains dominant.
    material.color.set('#ff2a38'); // accent
    material.opacity = 0.08;       // very subtle wash
    material.transparent = true;
    material.needsUpdate = true;
  });

  // ── Handlers (none) ──────────────────────────────────────────────
  group.userData.handlers = {
    click: null,
    hover: null,
    scroll: null,
  };

  // ── Cleanup ──────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();

    if (loadedTexture) {
      loadedTexture.dispose();
    }
    if (tempTexture) {
      tempTexture.dispose();
    }

    // No primitives or GSAP timelines to kill
  };

  return group;
}
